/**
 * Admin Dashboard Page
 * Premium admin dashboard with analytics and management
 */

import React, { useState, useEffect } from 'react';
import LoadingSpinner from '../components/LoadingSpinner';
import api from '../services/api';
import { useTheme } from '../context/useTheme';
import './AdminDashboard.css';

const AdminDashboard = () => {
  const { isDark } = useTheme();
  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    fetchDashboard();
  }, []);

  const fetchDashboard = async () => {
    try {
      const response = await api.get('/dashboard/admin');
      if (response.data?.dashboard) {
        setDashboard(response.data.dashboard);
        setError('');
      } else {
        setError('Invalid dashboard data received');
      }
    } catch (err) {
      const errorMsg = err.response?.data?.message || err.message || 'Failed to fetch dashboard';
      setError(errorMsg);
      console.error('Dashboard fetch error:', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchDashboard();
  };

  if (loading) {
    return <LoadingSpinner message="Loading admin dashboard..." />;
  }

  if (error && !dashboard) {
    return (
      <div className="admin-dashboard-page">
        <div className="admin-container">
          <div className="error-container">
            <h2>⚠️ Error Loading Dashboard</h2>
            <p>{error}</p>
            <button className="refresh-btn" onClick={handleRefresh}>
              🔄 Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`admin-dashboard-page ${isDark ? 'dark' : ''}`}>
      <div className="admin-container">
        <div className="dashboard-header">
          <h1>📊 Admin Dashboard</h1>
          <button 
            className="refresh-btn" 
            onClick={handleRefresh}
            disabled={refreshing}
          >
            🔄 {refreshing ? 'Refreshing...' : 'Refresh'}
          </button>
        </div>

        {/* Stats Grid */}
        <div className="stats-grid">
          <div className="stat-card">
            <span className="stat-icon">👥</span>
            <div className="stat-content">
              <h3>Total Users</h3>
              <p className="stat-value">{Math.max(0, dashboard?.totalUsers || 0)}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">📅</span>
            <div className="stat-content">
              <h3>Total Events</h3>
              <p className="stat-value">{Math.max(0, dashboard?.totalEvents || 0)}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">🎫</span>
            <div className="stat-content">
              <h3>Total Bookings</h3>
              <p className="stat-value">{Math.max(0, dashboard?.totalBookings || 0)}</p>
            </div>
          </div>

          <div className="stat-card">
            <span className="stat-icon">💰</span>
            <div className="stat-content">
              <h3>Total Revenue</h3>
              <p className="stat-value revenue">₹{Math.max(0, dashboard?.totalRevenue || 0)}</p>
            </div>
          </div>
        </div>

        {/* Bookings by Status */}
        <div className="chart-section">
          <h2>📈 Bookings by Status</h2>
          <div className="status-overview">
            {Object.entries(dashboard?.bookingsByStatus || {}).length > 0 ? (
              Object.entries(dashboard.bookingsByStatus).map(([status, count]) => (
                <div key={status} className="status-item">
                  <span className="status-name">{status ? status.charAt(0).toUpperCase() + status.slice(1) : 'Unknown'}</span>
                  <span className="status-count">{Math.max(0, count || 0)}</span>
                </div>
              ))
            ) : (
              <div className="empty-state">📭 No booking status data</div>
            )}
          </div>
        </div>

        {/* Recent Activity - Recent Bookings */}
        <div className="recent-activity-section">
          <h2>📋 Recent Bookings</h2>
          <div className="table-container">
            {dashboard?.recentBookings && dashboard.recentBookings.length > 0 ? (
              <table className="data-table">
                <thead>
                  <tr>
                    <th>User Name</th>
                    <th>Event Name</th>
                    <th>Date</th>
                    <th>Tickets</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboard.recentBookings?.slice(0, 10).map((booking, idx) => {
                    if (!booking?.userName || !booking?.eventName) return null;
                    return (
                      <tr key={booking?.id || idx}>
                        <td className="user-cell">
                          <span className="user-name">{booking.userName}</span>
                        </td>
                        <td className="event-cell">{booking.eventName}</td>
                        <td className="date-cell">
                          {booking.date ? new Date(booking.date).toLocaleDateString('en-IN') : 'N/A'}
                        </td>
                        <td className="tickets-cell">
                          <span className="ticket-badge">{Math.max(0, booking.tickets || 0)}</span>
                        </td>
                        <td className="status-cell">
                          <span className={`status-badge ${(booking.status || 'confirmed').toLowerCase()}`}>
                            {booking.status ? booking.status.charAt(0).toUpperCase() + booking.status.slice(1) : 'Confirmed'}
                          </span>
                        </td>
                      </tr>
                    );
                  }) || []}
                </tbody>
              </table>
            ) : (
              <div className="empty-state">📭 No recent bookings</div>
            )}
          </div>
        </div>

        {/* Top Events */}
        <div className="recent-activity-section">
          <h2>⭐ Top Events</h2>
          <div className="table-container">
            {dashboard?.topEvents && dashboard.topEvents.length > 0 ? (
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Event Name</th>
                    <th>Total Bookings</th>
                    <th>Revenue</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboard.topEvents?.slice(0, 10).map((event, idx) => {
                    if (!event?.eventName) return null;
                    const bookingCount = Math.max(0, event.bookings || 0);
                    return (
                      <tr key={event?.eventName || idx} className={idx === 0 ? 'top-highlight' : ''}>
                        <td className="event-name-cell">
                          {idx === 0 && '🏆 '}
                          <span className="event-name">{event.eventName}</span>
                        </td>
                        <td className="bookings-cell">
                          <span className="bookings-badge">{bookingCount}</span>
                        </td>
                        <td className="revenue-cell">₹{Math.max(0, event.revenue || 0)}</td>
                        <td className="status-cell">
                          <span className={`status-badge ${bookingCount > 50 ? 'sold-out' : 'active'}`}>
                            {bookingCount > 50 ? 'Sold Out' : 'Active'}
                          </span>
                        </td>
                      </tr>
                    );
                  }) || []}
                </tbody>
              </table>
            ) : (
              <div className="empty-state">📭 No events data</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
